use std::error::Error;
use std::fs;

use wgpu::util::DeviceExt;

const SOFTENING: f32 = 0.01;
const WORKGROUP_SIZE: u32 = 64;
const MAX_COUNT: usize = 2048;
const MAX_STEPS: usize = 200;

/// One kernel computes every acceleration from the positions a step starts
/// with; the other advances velocities and then positions. Dispatches inside
/// one compute pass run in order, so a step's integration sees all of its
/// accelerations and the next step's accelerations see the moved positions.
const SHADER: &str = r#"
struct Params {
    n: u32,
    dt: f32,
    pad0: u32,
    pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

const SOFTENING: f32 = 0.01;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.n; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + SOFTENING;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    n: u32,
    dt: f32,
    pad: [u32; 2],
}

struct Input {
    count: usize,
    steps: usize,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse_input(text: &str) -> Result<Input, Box<dyn Error>> {
    let mut tokens = text.split_whitespace();
    let mut next = || tokens.next().ok_or("input ended early");

    let count: usize = next()?.parse()?;
    let steps: usize = next()?.parse()?;
    let dt: f32 = next()?.parse()?;
    if !(1..=MAX_COUNT).contains(&count) {
        return Err(format!("count {count} outside 1..={MAX_COUNT}").into());
    }
    if steps > MAX_STEPS {
        return Err(format!("steps {steps} outside 0..={MAX_STEPS}").into());
    }

    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for _ in 0..count {
        let x: f32 = next()?.parse()?;
        let y: f32 = next()?.parse()?;
        let vx: f32 = next()?.parse()?;
        let vy: f32 = next()?.parse()?;
        pos.push([x, y]);
        vel.push([vx, vy]);
    }
    Ok(Input { count, steps, dt, pos, vel })
}

/// Runs `steps` steps on the GPU and returns the final positions and velocities.
async fn simulate(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), Box<dyn Error>> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
            apply_limit_buckets: false,
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot create GPU device: {e}"))?;

    let n = input.count as u32;
    let params = Params { n, dt: input.dt, pad: [0; 2] };
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC;

    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&input.pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&input.vel),
        usage: storage,
    });
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("acc"),
        size: (input.count * std::mem::size_of::<[f32; 2]>()) as u64,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let size = (input.count * std::mem::size_of::<[f32; 2]>()) as u64;
    let pos_read = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("pos_read"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let vel_read = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("vel_read"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let entry = |binding: u32, ty: wgpu::BufferBindingType| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer { ty, has_dynamic_offset: false, min_binding_size: None },
        count: None,
    };
    let storage_ty = wgpu::BufferBindingType::Storage { read_only: false };
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("particles"),
        entries: &[
            entry(0, wgpu::BufferBindingType::Uniform),
            entry(1, storage_ty),
            entry(2, storage_ty),
            entry(3, storage_ty),
        ],
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("particles"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: params_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: pos_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 2, resource: vel_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 3, resource: acc_buf.as_entire_binding() },
        ],
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("particles"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let make_pipeline = |entry_point: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry_point),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some(entry_point),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = make_pipeline("accelerate");
    let integrate = make_pipeline("integrate");

    let groups = n.div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_bind_group(0, &bind_group, &[]);
        for _ in 0..input.steps {
            pass.set_pipeline(&accelerate);
            pass.dispatch_workgroups(groups, 1, 1);
            pass.set_pipeline(&integrate);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &pos_read, 0, size);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &vel_read, 0, size);
    queue.submit(Some(encoder.finish()));

    let pos = read_back(&device, &pos_read)?;
    let vel = read_back(&device, &vel_read)?;
    Ok((pos, vel))
}

fn read_back(device: &wgpu::Device, buffer: &wgpu::Buffer) -> Result<Vec<[f32; 2]>, Box<dyn Error>> {
    let slice = buffer.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |result| {
        let _ = tx.send(result);
    });
    device.poll(wgpu::PollType::wait_indefinitely())?;
    rx.recv()??;
    let data = slice.get_mapped_range()?;
    let values: Vec<[f32; 2]> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    buffer.unmap();
    Ok(values)
}

fn summarize(pos: &[[f32; 2]], vel: &[[f32; 2]]) -> String {
    let n = pos.len() as f64;
    let (mut cx, mut cy) = (0.0f64, 0.0f64);
    for p in pos {
        cx += f64::from(p[0]);
        cy += f64::from(p[1]);
    }
    cx /= n;
    cy /= n;

    let (mut px, mut py, mut kinetic) = (0.0f64, 0.0f64, 0.0f64);
    for v in vel {
        let (vx, vy) = (f64::from(v[0]), f64::from(v[1]));
        px += vx;
        py += vy;
        kinetic += (vx * vx + vy * vy) / 2.0;
    }

    let mut spread_sq = 0.0f64;
    for p in pos {
        let dx = f64::from(p[0]) - cx;
        let dy = f64::from(p[1]) - cy;
        spread_sq += dx * dx + dy * dy;
    }
    let spread = (spread_sq / n).sqrt();

    format!(
        "CENTER {cx:.6} {cy:.6}\nMOMENTUM {px:.6} {py:.6}\nKINETIC {kinetic:.6}\nSPREAD {spread:.6}\n"
    )
}

fn main() -> Result<(), Box<dyn Error>> {
    let path = std::env::args().nth(1).ok_or("usage: particles <input-file>")?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse_input(&text)?;

    let (pos, vel) = if input.steps == 0 {
        (input.pos.clone(), input.vel.clone())
    } else {
        pollster::block_on(simulate(&input))?
    };

    print!("{}", summarize(&pos, &vel));
    Ok(())
}

